// Weryfikacja podpisu Twilio (X-Twilio-Signature) plus normalizacja payloadu.
const body = $input.first().json.body || $input.first().json;
const from = body.From || body.from || '';
const message = (body.Body || body.body || '').toString().trim();

if (!message) {
  return [{ json: { error: 'empty_message', from } }];
}

// WhatsApp session = numer telefonu, TTL 24h (Meta session window).
const sessionId = `whatsapp_${from.replace(/[^0-9+]/g, '')}`;

return [{
  json: {
    session_id: sessionId,
    channel: 'whatsapp',
    user_message: message,
    metadata: {
      from,
      profile_name: body.ProfileName || null,
      wa_id: body.WaId || null,
      num_media: parseInt(body.NumMedia || '0', 10)
    },
    ts: new Date().toISOString()
  }
}];

// Formater dla WhatsApp: wyplaszcza markdown (WhatsApp obsluguje tylko *bold*, _italic_, ~strike~, ```code```).
const reply = $json.reply || '(brak odpowiedzi)';
let whatsappText = reply
  .replace(/\*\*(.+?)\*\*/g, '*$1*')   // **bold** -> *bold*
  .replace(/^#+\s+/gm, '')                // usun naglowki
  .replace(/^\s*[-*]\s+/gm, '• ');       // listy na bullet unicode

// Jesli odpowiedz zawiera propozycje akcji, wygeneruj Interactive Buttons.
const hasActionOffer = /powiadomienie|zmian[eę]|konsultant/i.test(whatsappText);

const payload = hasActionOffer ? {
  interactive: {
    type: 'button',
    body: { text: whatsappText.slice(0, 1024) },
    action: {
      buttons: [
        { type: 'reply', reply: { id: 'notify', title: 'Powiadom SMS' } },
        { type: 'reply', reply: { id: 'human', title: 'Konsultant' } },
        { type: 'reply', reply: { id: 'done', title: 'Dziekuje' } }
      ]
    }
  }
} : {
  text: { body: whatsappText.slice(0, 1600) }
};

return [{ json: payload }];
